#include "session.h"
#include <cctype>
#include <cmath>
#include <sstream>
#include <algorithm>
#include <bit>
#include <cmath>

namespace war3 {
jass::Value ScriptSession::createEffect(const std::string& model,WorldPoint point,std::uint32_t target,const std::string& attachment,bool automatic) {
    if(model.empty() || model=="_")return runtime_.handle("effect",0);if(model.size()>1024 || effects_.size()>=8192)throw std::runtime_error("Effect definition or instance budget exceeded");if(target && !alive(target,NativeKind::Unit) && !alive(target,NativeKind::Item) && !alive(target,NativeKind::Destructable))return runtime_.handle("effect",0);auto h=create(NativeKind::Effect);auto e=std::make_shared<ScriptEffect>();e->id=h.bits;e->model=model;e->point=requireWorld().clamp(point);e->target=target;e->attachment=attachment;e->automatic=automatic;e->born=simulationTime_;if(automatic)e->fallbackExpires=simulationTime_+16;std::get<std::shared_ptr<ScriptEffect>>(object(h,NativeKind::Effect).state)=e;effects_[h.bits]=std::move(e);return h;
}
void ScriptSession::destroyEffect(std::uint32_t id) {if(!id || !alive(id,NativeKind::Effect))return;auto e=std::get<std::shared_ptr<ScriptEffect>>(objects_[id-handleBase].state);e->destroyed=simulationTime_;e->expires.reset();e->fallbackExpires=simulationTime_+16;destroy(runtime_.handle("effect",id),NativeKind::Effect);}
void ScriptSession::effectExpires(std::uint32_t id,double time) {if(!std::isfinite(time) || time<0 || time>simulationTime_+86400)throw std::runtime_error("Effect retirement exceeds supported range");auto found=effects_.find(id);if(found!=effects_.end())found->second->expires=time;}
void ScriptSession::effectsTick() {
    for(auto it=effects_.begin();it!=effects_.end();){auto e=it->second;if(e->target){if(alive(e->target,NativeKind::Unit)){auto u=units_.at(e->target);e->point={u->x,u->y};e->z=u->flyHeight;}else if(alive(e->target,NativeKind::Item)){auto item=items_.at(e->target);e->point={item->x,item->y};}else if(alive(e->target,NativeKind::Destructable)){auto d=destructables_.at(e->target);e->point=d->position;}else{e->target=0;if(!e->destroyed)destroyEffect(e->id);}}auto expires=e->expires?e->expires:e->fallbackExpires;if(expires && *expires<=simulationTime_ && (e->destroyed || e->automatic)){if(alive(e->id,NativeKind::Effect))destroy(runtime_.handle("effect",e->id),NativeKind::Effect);it=effects_.erase(it);}else ++it;}
}
std::vector<std::uint32_t> ScriptSession::spellVisual(const SpellInfo& spell,const char* field,std::uint32_t target,WorldPoint point,bool automatic) {
    std::vector<std::string> models;std::stringstream paths(definitions().field(spell.ability,"Profile",field));std::string model;while(std::getline(paths,model,',')){auto first=model.find_first_not_of(" \t\"");if(first==std::string::npos)continue;model=model.substr(first,model.find_last_not_of(" \t\"")-first+1);if(model!="_" && model!="-")models.push_back(model);}if(models.empty())return {};if(models.size()>64)throw std::runtime_error("Spell visual model budget exceeded");
    std::string name(field);for(auto& c:name)c=char(std::tolower(static_cast<unsigned char>(c)));std::string attach=name=="casterart"?"Casterattach":name=="specialart"?"Specialattach":name=="effectart"?"Effectattach":"Targetattach";float attachments=definitions().number(spell.ability,"Profile",attach+"count",1);if(attachments<0 || attachments>64 || attachments!=std::floor(attachments))throw std::runtime_error("Spell attachment count outside supported range");unsigned count=unsigned(attachments);std::vector<std::uint32_t> created;for(size_t i=0;i<std::max(models.size(),size_t(count));++i){auto key=attach+(i && i<count?std::to_string(i):"");auto attachment=count?definitions().field(spell.ability,"Profile",key,"origin"):"origin";auto h=createEffect(models[i%models.size()],point,target,attachment,automatic);if(h.bits)created.push_back(h.bits);}return created;
}
void ScriptSession::releaseBuff(UnitBuff& buff) {retireUnitCasterBuff(buff);if(buff.kind==BuffKind::PhaseShift){++fogRevision_;if(alive(buff.target,NativeKind::Unit)){auto u=units_.at(buff.target);if(!u->removing && std::bit_cast<float>(u->life.bits())>0){SpellInfo art;art.ability=buff.id;for(auto visual:spellVisual(art,"Specialart",0,{u->x,u->y}))effects_.at(visual)->z=u->displayFlyHeight();}}}if(buff.healthBonus>0 && alive(buff.target,NativeKind::Unit)){auto u=units_.at(buff.target);u->maxLife=jass::Real::fromBits(std::bit_cast<std::uint32_t>(std::max(1.f,std::bit_cast<float>(u->maxLife.bits())-buff.healthBonus)));float life=std::bit_cast<float>(u->life.bits());u->life=jass::Real::fromBits(std::bit_cast<std::uint32_t>(life>0?std::clamp(life-(buff.kind==BuffKind::DrainBonus?0:buff.healthBonus),1.f,std::bit_cast<float>(u->maxLife.bits())):0.f));buff.healthBonus=0;}if(buff.manaBonus>0 && alive(buff.target,NativeKind::Unit)){auto u=units_.at(buff.target);float maximum=std::max(0.f,std::bit_cast<float>(u->maxMana.bits())-buff.manaBonus);u->maxMana=jass::Real::fromBits(std::bit_cast<std::uint32_t>(maximum));u->mana=jass::Real::fromBits(std::bit_cast<std::uint32_t>(std::min(std::bit_cast<float>(u->mana.bits()),maximum)));buff.manaBonus=0;}if(buff.kind==BuffKind::Morph && alive(buff.target,NativeKind::Unit)){auto u=units_.at(buff.target);if(!u->removing && std::bit_cast<float>(u->life.bits())>0){SpellInfo art;art.ability=buff.id;spellVisual(art,"Effectart",buff.target,{u->x,u->y});}}for(auto id:buff.visuals){auto found=effects_.find(id);if(found!=effects_.end() && found->second->groundAnchor){auto e=found->second;if(alive(e->target,NativeKind::Unit)){auto u=units_.at(e->target);e->point={u->x,u->y};e->z=u->flyHeight;}e->target=0;}destroyEffect(id);}buff.visuals.clear();}
void ScriptSession::bindEffectNatives() {
    auto text=[](const jass::Value& v){return v.text?*v.text:std::string{};};
    auto image=[this](jass::Value value){return std::get<std::shared_ptr<ScriptImage>>(object(value,NativeKind::Image).state);};
    auto number=[](jass::Value value){float result=std::bit_cast<float>(value.bits);if(!std::isfinite(result) || std::abs(result)>1000000)throw std::runtime_error("Image coordinate outside supported range");return result;};
    bind("CreateImage","image",{"string","real","real","real","real","real","real","real","real","real","integer"},[this,text,number](auto& vm,auto a){auto path=text(a[0]);if(path.empty() || path=="_")return vm.handle("image",0);if(path.size()>1024 || images_.size()>=8192)throw std::runtime_error("Image definition or instance budget exceeded");auto state=std::make_shared<ScriptImage>();state->texture=path;for(unsigned i=0;i<3;++i){state->size[i]=number(a[1+i]);state->position[i]=number(a[4+i]);state->origin[i]=number(a[7+i]);}if(state->size[0]<0 || state->size[1]<0 || state->size[2]<0)throw std::runtime_error("Negative image dimensions");state->type=std::bit_cast<std::int32_t>(a[10].bits);auto h=create(NativeKind::Image);std::get<std::shared_ptr<ScriptImage>>(object(h,NativeKind::Image).state)=state;images_.emplace(h.bits,std::move(state));return h;});
    bind("DestroyImage","nothing",{"image"},[this](auto& vm,auto a){if(a[0].bits && alive(a[0].bits,NativeKind::Image)){images_.erase(a[0].bits);destroy(a[0],NativeKind::Image);}return vm.nothing();});
    bind("ShowImage","nothing",{"image","boolean"},[image](auto& vm,auto a){if(a[0].bits)image(a[0])->visible=a[1].bits!=0;return vm.nothing();});
    bind("SetImagePosition","nothing",{"image","real","real","real"},[image,number](auto& vm,auto a){if(a[0].bits){auto state=image(a[0]);for(unsigned i=0;i<3;++i)state->position[i]=number(a[i+1]);}return vm.nothing();});
    bind("SetImageColor","nothing",{"image","integer","integer","integer","integer"},[image](auto& vm,auto a){if(a[0].bits){auto byte=[&](unsigned i){return std::uint32_t(std::clamp(std::bit_cast<std::int32_t>(a[i].bits),0,255));};image(a[0])->color=(byte(4)<<24)|(byte(1)<<16)|(byte(2)<<8)|byte(3);}return vm.nothing();});
    bind("SetImageConstantHeight","nothing",{"image","boolean","real"},[image,number](auto& vm,auto a){if(a[0].bits){auto state=image(a[0]);state->fixedHeight=a[1].bits!=0;state->constantHeight=number(a[2]);}return vm.nothing();});
    bind("SetImageRender","nothing",{"image","boolean"},[image](auto& vm,auto a){if(a[0].bits)image(a[0])->render=a[1].bits!=0;return vm.nothing();});
    bind("SetImageRenderAlways","nothing",{"image","boolean"},[image](auto& vm,auto a){if(a[0].bits)image(a[0])->renderAlways=a[1].bits!=0;return vm.nothing();});
    bind("SetImageAboveWater","nothing",{"image","boolean","boolean"},[image](auto& vm,auto a){if(a[0].bits){auto state=image(a[0]);state->aboveWater=a[1].bits!=0;state->useWaterAlpha=a[2].bits!=0;}return vm.nothing();});
    bind("SetImageType","nothing",{"image","integer"},[image](auto& vm,auto a){if(a[0].bits)image(a[0])->type=std::bit_cast<std::int32_t>(a[1].bits);return vm.nothing();});
    bind("AddSpecialEffect","effect",{"string","real","real"},[this,text](auto&,auto a){return createEffect(text(a[0]),{jass::Real::fromBits(a[1].bits),jass::Real::fromBits(a[2].bits)});});
    bind("AddSpecialEffectLoc","effect",{"string","location"},[this,text](auto&,auto a){return createEffect(text(a[0]),std::get<WorldPoint>(object(a[1],NativeKind::Location).state));});
    bind("AddSpecialEffectTarget","effect",{"string","widget","string"},[this,text](auto&,auto a){return createEffect(text(a[0]),{},a[1].bits,text(a[2]));});
    bind("DestroyEffect","nothing",{"effect"},[this](auto& vm,auto a){destroyEffect(a[0].bits);return vm.nothing();});
}
}
